import{_ as n,c as s,o as a,ag as t}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Writing SITREPs","description":"","frontmatter":{"title":"Writing SITREPs"},"headers":[],"relativePath":"general/writing-sitreps.md","filePath":"general/writing-sitreps.md","lastUpdated":null}'),i={name:"general/writing-sitreps.md"};function r(l,e,o,p,c,u){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="writing-sitreps" tabindex="-1">Writing SITREPs <a class="header-anchor" href="#writing-sitreps" aria-label="Permalink to &quot;Writing SITREPs&quot;">​</a></h1><h2 id="sitrep-guidance" tabindex="-1">SITREP Guidance <a class="header-anchor" href="#sitrep-guidance" aria-label="Permalink to &quot;SITREP Guidance&quot;">​</a></h2><p><strong>Purpose</strong>: To ensure clear, concise, and informative Situation Reports (SITREPs) that effectively communicate significant events, their implications, and the next steps to relevant stakeholders.</p><p><strong>Location</strong>: SITREP bullets should be written and stored in a shared, secured platform, such as SIPR J39 OneNote, accessible to all relevant team members and leaders.</p><h3 id="broad-steps" tabindex="-1">Broad Steps <a class="header-anchor" href="#broad-steps" aria-label="Permalink to &quot;Broad Steps&quot;">​</a></h3><ul><li><p><strong>Identify Significant Events</strong>: Maintain a running list of notable events and actions throughout the week, including accomplishments, challenges, and lessons learned.</p></li><li><p><strong>Categorize Events</strong>: Sort each event under the appropriate topic or theme to maintain focus and clarity.</p></li><li><p><strong>Write SITREP Bullets</strong>: For each event, follow the &quot;One-Topic-Per-Bullet&quot; rule and include the following elements:</p><ul><li><strong>What</strong>: Describe the event or action that occurred using clear and concise language.</li><li><strong>So What</strong>: Explain the implications or significance of the event, including its impact on the mission, objectives, or team.</li><li><strong>Now What</strong>: Detail the next steps, expectations, or follow-up actions required, and how they contribute to the overall mission or objectives.</li></ul></li><li><p><strong>Spell Out Acronyms and Organizations</strong>: Ensure all acronyms and organizational names are spelled out on first use to maintain clarity for readers at all chain of command levels.</p></li><li><p><strong>Review and Edit</strong>: Carefully review the SITREP bullets for grammar, style, and content, ensuring they are both concise and informative.</p></li><li><p><strong>Share with Relevant Stakeholders</strong>: Distribute the SITREP bullets to relevant team members, leaders, and stakeholders in a timely manner, ensuring they have the information needed to make informed decisions.</p></li></ul><h3 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h3><ul><li><p><strong>Topic</strong> <strong>[describe the topic or theme of the bullet]</strong></p></li><li><p><strong>What</strong> <strong>[the event or action that occurred]</strong></p></li><li><p><strong>So What</strong> <strong>[the implications or significance of the event]</strong></p></li><li><p><strong>Now What</strong> <strong>[the next steps, expectations, or follow-up actions required]</strong></p></li></ul><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><ul><li><p><strong>Correct SITREP Line Example</strong></p><ul><li>UNIT NAME HERE successfully completed a two-day emergency response (ER) technical exchange (TE) with the Forces of the Country Here (FCH); 38 participants qualified in the required skills; the ER TE enhanced team readiness for real-world emergencies in the region here; FCH leadership requests future quarterly refresher training sessions.</li></ul></li><li><p><strong>Incorrect SITREP Line Example</strong></p><ul><li>Completed training exercise and did really well!</li></ul></li></ul><h3 id="sitrep-ai-prompt-template" tabindex="-1">SITREP AI Prompt Template <a class="header-anchor" href="#sitrep-ai-prompt-template" aria-label="Permalink to &quot;SITREP AI Prompt Template&quot;">​</a></h3><p>See best practices <a href="https://socom.sharepoint-mil.us/sites/socsouth-j3-jedpsyop/SiteAssets/SOCSOUTH%20J39%20PSYOP%20(CUI)/MISO/SOPs%20and%20Guides.one" target="_blank" rel="noreferrer">NIPR SITREP Workflow</a>.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>   1. Guidance</span></span>
<span class="line"><span>1. **Write SITREP Bullets**: For each event, follow the &quot;One-Topic-Per-Bullet&quot; rule and include the following elements:</span></span>
<span class="line"><span>   1. **What**: Describe the event or action that occurred, using clear and concise language.</span></span>
<span class="line"><span>   1. **So What**: Explain the implications or significance of the event, including its impact on the mission, objectives, or team.</span></span>
<span class="line"><span>   1. **Now What**: Detail the next steps, expectations, or follow-up actions required and how they contribute to the overall mission or objectives.</span></span>
<span class="line"><span>1. **Spell Out Acronyms and Organizations**: Ensure that all acronyms and organizational names are spelled out on first use to maintain clarity for readers at all chain of command levels.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Examples</span></span>
<span class="line"><span>examples are just examples with placeholder data.</span></span>
<span class="line"><span>Correct SITREP Bullet Example</span></span>
<span class="line"><span>UNIT NAME HERE successfully completed a two-day emergency response (ER) technical exchange (TE) with the Forces of the Country Here (FCH); 38 participants qualified in the required skills; the ER TE enhanced team readiness for real-world emergencies in the region here; FCH leadership requests future quarterly refresher training sessions.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Incorrect SITREP Bullet Example</span></span>
<span class="line"><span>Completed training exercise and did really well!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The first time: Ask me questions that a Commander might ask to get more information about these bullets. These questions should help guide me to write better sitrep bullets:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#Varables for User to Use Below:</span></span>
<span class="line"><span>Take into account these variables which will be used in the output:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   1. Events</span></span>
<span class="line"><span>- **Event 1**: [describe the event or action that occurred](Briefly)</span></span>
<span class="line"><span>- **Event 2**: [describe the event or action that occurred](Briefly)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- My Org = ORG_HERE</span></span>
<span class="line"><span>- My Section = SECTION_HERE</span></span>
<span class="line"><span>- My AOR = AOR_HERE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br></div></div><ol><li><strong>Review and Edit</strong>: Carefully review the SITREP bullets for grammar, style, and content, ensuring they are both concise and informative.</li></ol><p>[Up] [Required]</p>`,15)])])}const m=n(i,[["render",r]]);export{d as __pageData,m as default};
